import * as React from "react";

export type StampIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function StampIcon({ size = 20, ...props }: StampIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8" />
      <circle cx="12" cy="12" r="5.2" strokeDasharray="2.4 1.8" />
      <path d="M12 8.5v7M8.5 12h7" />
    </svg>
  );
}
